function v({registerIndicator:g,nulls:y}){g({id:"oa-adosc",name:"Chaikin A/D Oscillator (ADOSC)",category:"Volume",placement:"pane",inputs:[{key:"shortPeriod",type:"number",label:"Short Period",default:3,min:1,max:5e3,step:1},{key:"longPeriod",type:"number",label:"Long Period",default:10,min:1,max:5e3,step:1}],plots:[{key:"adosc",type:"line",title:"ADOSC",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,u){const P=Math.max(1,Math.floor(Number(u.shortPeriod)||3)),A=Math.max(1,Math.floor(Number(u.longPeriod)||10)),F=1e-10,w=2/(P+1),h=2/(A+1),x=1-h,N=new Array(r.length).fill(NaN);let i=0,a=1,e=0,o=0;for(let t=0;t<r.length;t++){const n=r[t],c=Number(n.high),m=Number(n.low),d=Number(n.close),E=Number.isFinite(n.volume)?n.volume:0;let l=0;if(Number.isFinite(c)&&Number.isFinite(m)&&Number.isFinite(d)){const p=c-m;p!==0&&(l=(2*d-c-m)/p*E)}Number.isFinite(l)||(l=0),i=t===0?l:i+l;const s=1-a,b=a>F;e=w*(i-e)+e;const M=b?s!==0?e/s:NaN:e;o=h*(i-o)+o;const k=b?s!==0?o/s:NaN:o;a=x*a;const f=M-k;N[t]=Number.isFinite(f)?f:NaN}return{adosc:y(N)}}})}export{v as default};
